from scipy.optimize import least_squares
def mdl(p):
    a,b,c,d,e,w,ph,s,q=p
    return a/P + b*P + c*P**2 + d*t*P + e*t*P**2 + s*np.sin(w*t+ph)*P + q*np.sin(w*t+ph)
best=None
